using System;
using System.IO;
using System.IO.Pipes;
using System.Security.AccessControl;
using System.Security.Principal;
using System.Text;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
using System.Windows.Forms;
using Microsoft.Web.WebView2.Core;

internal static class PulseTransferBootstrap {
 internal static readonly string Root=Environment.GetEnvironmentVariable("JAGO_SUITE_ROOT")??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Jago Studio Suite");
 internal static string Argument(string[] args,string key){for(int i=0;i<args.Length-1;i++)if(args[i]==key)return Path.GetFullPath(args[i+1]);return null;}
 internal static string Pipe(string key){if(Environment.GetEnvironmentVariable("JAGO_WORKSPACE_TAB_ROOT")!=null)key+="."+Environment.GetEnvironmentVariable("JAGO_WORKSPACE_TAB_ID");string isolated="";if(Environment.GetEnvironmentVariable("JAGO_SUITE_ROOT")!=null)using(var sha=System.Security.Cryptography.SHA256.Create())isolated="."+BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(Root))).Replace("-","").Substring(0,12);return "JagoSuite."+WindowsIdentity.GetCurrent().User.Value.Replace('-','_')+isolated+"."+key;}
 internal static bool Send(string key,string text,int timeout){try{using(var pipe=new NamedPipeClientStream(".",Pipe(key),PipeDirection.Out)){pipe.Connect(timeout);using(var writer=new StreamWriter(pipe,new UTF8Encoding(false))){writer.WriteLine(text);writer.Flush();}}return true;}catch{return false;}}
 internal static bool Forward(string[] args){string file=Argument(args,"--receive");return file!=null&&Send("pulse",file,1000);}
}
internal sealed class PulseSoundTransferHost {
 readonly Form owner;readonly CoreWebView2 core;readonly string document;readonly JavaScriptSerializer json=new JavaScriptSerializer{MaxJsonLength=110000000,RecursionLimit=256};
 NamedPipeServerStream listening;bool closed,ready;readonly System.Collections.Generic.Queue<string> pending=new System.Collections.Generic.Queue<string>();
 internal PulseSoundTransferHost(Form form,CoreWebView2 browser,string uri){owner=form;core=browser;document=uri;Directory.CreateDirectory(PulseTransferBootstrap.Root);string connection=Path.Combine(PulseTransferBootstrap.Root,"connections.json");JagoHostSecurity.Locked(connection,()=>{System.Collections.Generic.Dictionary<string,string> all;try{all=json.Deserialize<System.Collections.Generic.Dictionary<string,string>>(JagoHostSecurity.ReadBounded(connection,1000000));}catch{all=new System.Collections.Generic.Dictionary<string,string>();}if(all==null)all=new System.Collections.Generic.Dictionary<string,string>();all["pulse"]=Application.ExecutablePath;JagoHostSecurity.Atomic(connection,json.Serialize(all));});
 core.WebMessageReceived+=Message;core.NavigationCompleted+=async(s,e)=>{if(!e.IsSuccess)return;for(int i=0;i<100&&!closed;i++){if(await core.ExecuteScriptAsync("!!window.PulseSoundImport")=="true"){ready=true;break;}await Task.Delay(100);}if(!ready||closed)return;string initial=PulseTransferBootstrap.Argument(Environment.GetCommandLineArgs(),"--receive");if(initial!=null)Deliver(initial);while(pending.Count>0)Deliver(pending.Dequeue());if(Program.TransferTest!=null)Probe();};owner.FormClosed+=(s,e)=>{closed=true;if(listening!=null)listening.Dispose();};Task.Run((Action)Listen);}
 static string ReadPath(Stream stream){using(var reader=new StreamReader(stream,Encoding.UTF8)){var text=new StringBuilder();for(int i=0;i<32768;i++){int c=reader.Read();if(c<0||c=='\n')return text.ToString().TrimEnd('\r');text.Append((char)c);}throw new InvalidDataException("Transfer path is too long.");}}
 void Listen(){while(!closed)try{var security=new PipeSecurity();security.SetAccessRuleProtection(true,false);security.AddAccessRule(new PipeAccessRule(WindowsIdentity.GetCurrent().User,PipeAccessRights.FullControl,AccessControlType.Allow));using(var pipe=new NamedPipeServerStream(PulseTransferBootstrap.Pipe("pulse"),PipeDirection.In,1,PipeTransmissionMode.Byte,PipeOptions.None,4096,4096,security)){listening=pipe;pipe.WaitForConnection();var read=Task.Run(()=>ReadPath(pipe));if(!read.Wait(5000))continue;string path=read.Result;if(!closed)owner.BeginInvoke((Action)(()=>{if(ready)Deliver(path);else if(pending.Count<8)pending.Enqueue(path);}));}}catch{if(!closed)System.Threading.Thread.Sleep(100);}}
 void Deliver(string input){try{string path=Path.GetFullPath(input);if(!path.EndsWith(".jagotransfer",StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Choose a Sound transfer file.");var pack=json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(JagoHostSecurity.ReadBounded(path,110000000));if(Convert.ToString(pack["format"])!="jago-studio-transfer"||Convert.ToString(pack["sourceStudio"])!="music")throw new InvalidDataException("Pulse expects a Sound audio transfer here.");core.PostWebMessageAsJson(json.Serialize(new{type="jago-suite-receive",package=pack}));if(Program.TransferTest==null){if(owner.WindowState==FormWindowState.Minimized)owner.WindowState=FormWindowState.Normal;owner.Show();owner.Activate();}}catch(Exception e){core.PostWebMessageAsJson(json.Serialize(new{type="pulse-transfer-error",message=e.Message}));}}
 void Message(object sender,CoreWebView2WebMessageReceivedEventArgs e){if(closed||!JagoHostSecurity.Trusted(e.Source,document))return;try{var data=json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(e.WebMessageAsJson);object kind;if(!data.TryGetValue("type",out kind)||Convert.ToString(kind)!="jago-suite-ack")return;Guid id;if(!data.ContainsKey("id")||!Guid.TryParse(Convert.ToString(data["id"]),out id))return;Task.Run(()=>PulseTransferBootstrap.Send("music","ack|"+id,500));}catch{}}
 async void Probe(){try{string path=Path.Combine(Program.TransferTest,"probe.js");if(!File.Exists(path))throw new FileNotFoundException("Missing isolated transfer probe.");await core.ExecuteScriptAsync(JagoHostSecurity.ReadBounded(path,2000000));string result="null";for(int i=0;i<900&&!closed;i++){result=await core.ExecuteScriptAsync("window.suiteTestResult||null");if(result!="null")break;await Task.Delay(100);}Directory.CreateDirectory(Program.TransferTest);File.WriteAllText(Path.Combine(Program.TransferTest,"result.json"),result);if(!closed)owner.Close();}catch(Exception e){Directory.CreateDirectory(Program.TransferTest);File.WriteAllText(Path.Combine(Program.TransferTest,"result.json"),json.Serialize(new{ok=false,error=e.ToString()}));if(!closed)owner.Close();}}
}
